class Solution {
public:
    vector<vector<int>> allPathsSourceTarget(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<vector<int>> res;
        vector<int> path = {0};
        auto dfs = [&](auto& self, int u) -> void {
            if (u == n - 1) {
                res.push_back(path);
                return;
            }
            for (int v : graph[u]) {
                path.push_back(v);
                self(self, v);
                path.pop_back();
            }
        };
        dfs(dfs, 0);
        return res;
    }
};

class Solution {
    public List<List<Integer>> allPathsSourceTarget(int[][] graph) {
        List<List<Integer>> res = new ArrayList<>();
        List<Integer> path = new ArrayList<>();
        path.add(0);
        dfs(0, graph.length - 1, graph, path, res);
        return res;
    }
    private void dfs(int u, int target, int[][] graph, List<Integer> path, List<List<Integer>> res) {
        if (u == target) {
            res.add(new ArrayList<>(path));
            return;
        }
        for (int v : graph[u]) {
            path.add(v);
            dfs(v, target, graph, path, res);
            path.remove(path.size() - 1);
        }
    }
}

var allPathsSourceTarget = function(graph) {
    const n = graph.length;
    const res = [];
    const path = [0];
    function dfs(u) {
        if (u === n - 1) {
            res.push([...path]);
            return;
        }
        for (const v of graph[u]) {
            path.push(v);
            dfs(v);
            path.pop();
        }
    }
    dfs(0);
    return res;
};
